<?php
declare(strict_types=1);require_once __DIR__.'/config/sales_step15.php';$error=null;$rows=[];$m=['original'=>0.0,'returns'=>0.0,'effective'=>0.0,'collected'=>0.0,'refunds'=>0.0,'receivable'=>0.0,'credit_due'=>0.0];
try{$pdo=business_db();sales_step15_ensure($pdo);sales_step15_backfill($pdo);$ctx=sales_step15_context($pdo);$orgId=(int)$ctx['organization_id'];$rows=sales_step15_sales_rows($pdo,$orgId);foreach($rows as $r){if($r['sale_status']!=='active')continue;$m['original']+=(float)$r['original_charge'];$m['returns']+=(float)$r['return_credit'];$m['effective']+=(float)$r['effective_charge'];$m['collected']+=(float)$r['gross_collected'];$m['refunds']+=(float)$r['refund_amount'];$m['receivable']+=(float)$r['receivable_amount'];$m['credit_due']+=(float)$r['customer_credit_due'];}}catch(Throwable $e){$error=$e->getMessage();}
function rv_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function rv_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Customer Receivables - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/step10.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="sales_fulfillment.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 15 • Customer Receivables</small></span></a><div class="os-top-actions"><a class="os-btn" href="product_payments.php">Receive Payment</a><a class="os-btn" href="sales_refunds.php">Refunds</a><a class="os-btn primary" href="sales_fulfillment.php">Fulfillment</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">After-Sales</div><nav class="os-nav"><a href="customer_center.php"><i class="dot"></i>Customers</a><a href="sales_fulfillment.php"><i class="dot"></i>Fulfillment</a><a href="sales_invoice.php"><i class="dot"></i>Invoices</a><a href="sales_delivery.php"><i class="dot"></i>Delivery</a><a href="sales_returns.php"><i class="dot"></i>Returns</a><a href="sales_refunds.php"><i class="dot"></i>Refunds</a><a class="active" href="sales_receivables.php"><i class="dot"></i>Receivables</a><a href="crm_followups.php"><i class="dot"></i>Follow-ups</a></nav></aside><main class="os-main"><section class="os-hero s10-hero"><div class="os-kicker">STEP 15G • CUSTOMER RECEIVABLES</div><h1>Separate what was sold, what was returned, what was paid and what is still due.</h1><p>Receivable = Effective Charge − Net Collected. Customer Credit Due appears separately when net collected is higher than the post-return charge.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'RECEIVABLES LIVE':'Review required' ?></span><span class="os-chip"><?= count($rows) ?> sale ledgers</span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Receivable diagnostic:</strong> <?= rv_h($error) ?></div><?php endif;?><section class="s10-kpis"><div class="s10-kpi"><small>Effective Charge</small><strong><?= rv_m($m['effective']) ?></strong><span>Original <?= rv_m($m['original']) ?> − Return credits <?= rv_m($m['returns']) ?></span></div><div class="s10-kpi"><small>Net Collected</small><strong><?= rv_m(max(0,$m['collected']-$m['refunds'])) ?></strong><span>Gross collected <?= rv_m($m['collected']) ?> − Refunds <?= rv_m($m['refunds']) ?></span></div><div class="s10-kpi"><small>Receivable</small><strong><?= rv_m($m['receivable']) ?></strong><span>Still due from customers</span></div><div class="s10-kpi"><small>Customer Credit Due</small><strong><?= rv_m($m['credit_due']) ?></strong><span>Potential refund/credit action required</span></div></section><?php if(!$error):?><section class="os-card" style="margin-top:14px"><h2>Sale-wise Customer Balance</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Order / Customer</th><th>Original</th><th>Return Credit</th><th>Effective</th><th>Gross Paid</th><th>Refund</th><th>Net Collected</th><th>Receivable</th><th>Credit Due</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b>#<?= (int)$r['order_id'] ?> • <?= rv_h($r['customer_name']) ?></b><small><?= rv_h($r['order_date'].' • '.strtoupper($r['sale_status'])) ?></small></td><td><?= rv_m($r['original_charge']) ?></td><td><?= rv_m($r['return_credit']) ?></td><td><b><?= rv_m($r['effective_charge']) ?></b></td><td><?= rv_m($r['gross_collected']) ?></td><td><?= rv_m($r['refund_amount']) ?></td><td><?= rv_m($r['net_collected']) ?></td><td><b><?= rv_m($r['receivable_amount']) ?></b></td><td><?= rv_m($r['customer_credit_due']) ?></td><td><?php if((float)$r['receivable_amount']>0.009):?><a href="product_payments.php">Receive payment →</a><?php elseif((float)$r['customer_credit_due']>0.009):?><a href="sales_refunds.php?order=<?= (int)$r['order_id'] ?>">Review refund →</a><?php else:?>Balanced<?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="10">No finalized Product Sales yet.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?><div class="os-footer-note"><strong>Balance rule:</strong> refunds do not erase original customer payments; both are preserved so net collection remains auditable.</div></main></div></body></html>